#pragma once
// The enemy a character of a given level is scored against: median Common / Champion / Hero monster of
// database.arz 1.3.1.1 (+ GDX1..3) at that level. Generated by re/tools/enemy_table.py into
// re/EnemyByLevel.tsv (what each column is and what it leaves out: that script's header); the table in
// enemy.cpp is that file (tests/test_enemy.cpp compares them). Difficulty adjustments are not included.
namespace gdc::enemy {

struct Enemy {
  double oa = 0, da = 0;    // combatformulas.dbr ability equations on the monster's bio record
  double hit = 0;           // one skill hit, all damage types (flat direct damage of the skill record)
  double hit_physical = 0;  // its physical part: what armor works against
};

// Linear between the table's levels; clamped to its first / last row.
Enemy at(double level);

}  // namespace gdc::enemy
